  "Applications connectées": "Connected apps",
  "Pour interroger Pécule depuis l'appli Claude (web, ordinateur, iPhone) : dans Claude, Personnaliser → Connecteurs → Ajouter un connecteur personnalisé, avec cette adresse. Pécule te demande alors de te connecter et de choisir entre lecture seule et lecture et actions.": "To query Pécule from the Claude app (web, desktop, iPhone): in Claude, Customise → Connectors → Add custom connector, with this address. Pécule then asks you to sign in and choose between read-only and read and actions.",
