  "Révoquer « {nom} » ? Le raccourci qui l'utilise ne fonctionnera plus.": "Revoke “{nom}”? The shortcut that uses it will stop working.",
  "Copié": "Copied",
  "Raccourci iPhone « Envoyer à Pécule »": "iPhone shortcut “Send to Pécule”",
  "Depuis la feuille de partage (Mail, Fichiers, Photos…), envoie un PDF ou une photo : Claude le reconnaît et le range dans Factures ou dans le coffre de documents.": "From the share sheet (Mail, Files, Photos…), send a PDF or a photo: Claude recognises it and files it under Invoices or in the document vault.",
