  "Masquer le mode d'emploi": "Hide instructions",
  "Mode d'emploi": "Instructions",
  "App Raccourcis → « + » → nommez le raccourci « Envoyer à Pécule ».": "Shortcuts app → “+” → name the shortcut “Send to Pécule”.",
  "Réglages du raccourci (ⓘ) : activez « Afficher dans la feuille de partage », types acceptés : Fichiers, PDF, Images.": "Shortcut settings (ⓘ): turn on “Show in Share Sheet”, accepted types: Files, PDFs, Images.",
  "Ajoute l'action « Obtenir le contenu de l'URL » :": "Add the “Get Contents of URL” action:",
  "(après « name= », insérez la variable « Entrée du raccourci → Nom »).": "(after “name=”, insert the “Shortcut Input → Name” variable).",
  "Méthode POST ; en-tête « Authorization » = le jeton copié (« Bearer pec_… ») ; corps de la requête : Fichier → « Entrée du raccourci ».": "Method POST; “Authorization” header = the copied token (“Bearer pec_…”); request body: File → “Shortcut Input”.",
