  "Tes objectifs": "Your goals",
  "Un objectif = un projet (voyage, travaux, voiture, apport…), un montant et une date. Relie-le à un livret ou un placement : l'avancement suit sa valeur, et Pécule calcule le versement mensuel pour tenir la date.": "A goal = a project (trip, building work, car, deposit…), an amount and a date. Link it to a savings account or an investment: progress follows its value, and Pécule works out the monthly amount needed to meet the date.",
