  "Opération supprimée": "Transaction deleted",
  "Supprimer cette opération": "Delete this transaction",
  "Solde enregistré": "Balance saved",
  "Solde du compte": "Account balance",
  "Ce compte est alimenté par une banque : la saisie à la main est réservée aux comptes créés à la main.": "This account is fed by a bank: manual entry is reserved for accounts created by hand.",
  "Le montant ne peut pas être nul.": "The amount can't be zero.",
  "La date ne peut pas être dans le futur.": "The date can't be in the future.",
  "Donne un libellé à l'opération.": "Give the transaction a label.",
  "Seule une opération saisie à la main peut être supprimée.": "Only a manually entered transaction can be deleted.",
  "Créer un compte à la main": "Create an account by hand",
  "Solde illisible": "Unreadable balance",
  "Compte créé": "Account created",
  "Un compte tenu à la main : aucune banque ne l'alimente, tu y ajoutes ses opérations (écran Opérations) ou tu y importes un fichier.": "An account kept by hand: no bank feeds it, you add its transactions (Transactions screen) or import a file into it.",
  "Créer le compte": "Create the account",
  "Importer des documents": "Import documents",
  "importer dossier documents lot bulletins avis releves depot massif": "import folder documents batch payslips notices statements bulk upload",
  "Fichiers du {date}": "Files from {date}",
  "Glisse ici un dossier ou des fichiers": "Drag a folder or files here",
  "Préparation des fichiers… {a} sur {b}": "Preparing files… {a} of {b}",
  "Envoi… {a} sur {b}": "Uploading… {a} of {b}",
  "Choisir un dossier": "Choose a folder",
  "Choisir des fichiers": "Choose files",
  "Chaque fichier est rangé au coffre. Ceux que Pécule sait lire donnent une proposition, que tu relis avant qu'elle ne soit écrite dans tes écrans ; tout import peut être annulé. La lecture passe par ton fournisseur d'IA : le coût est estimé avant, mesuré ensuite, et plafonné par lot.": "Every file is filed in the vault. Those Pécule can read produce a proposal, which you review before it is written to your screens; any import can be undone. Reading goes through your AI provider: the cost is estimated beforehand, measured afterwards and capped per batch.",
  "annulé": "undone",
