  "PDF, photos, exports de la banque : chaque fichier est rangé, et Pécule lit ceux qu'il reconnaît (bulletins de paie, avis d'impôt, relevés, contrats, factures) pour te proposer leurs données. Rien n'est écrit sans ta validation.": "PDFs, photos, bank exports: every file is filed, and Pécule reads the ones it recognises (payslips, tax notices, statements, contracts, invoices) to suggest their data. Nothing is written without your approval.",
