  "Ce que tu possèdes (comptes, épargne, biens, crypto) moins ce que tu dois encore. Les biens et les crédits communs comptent pour ta part.": "What you own (accounts, savings, property, crypto) minus what you still owe. Shared assets and loans count for your share.",
  "Ce qu'il y a sur tes comptes aujourd'hui. Les achats par carte à débit différé pas encore prélevés n'en sont pas déduits.": "What is in your accounts today. Deferred-debit card purchases not yet charged are not deducted.",
  "Revenus du mois moins dépenses du mois. Les mouvements entre tes comptes et les versements d'épargne ne comptent pas.": "This month's income minus this month's spending. Transfers between your accounts and savings deposits don't count.",
