  "Surveiller mes soldes": "Watch my balances",
  "Pécule te prévient quand un compte est sous son seuil, ou va y passer.": "Pécule warns you when an account is below its threshold, or about to be.",
  "Seuil": "Threshold",
  "En dessous de ce montant, un compte est signalé. Un montant négatif prévient avant la limite d'un découvert autorisé.": "Below this amount, an account is flagged. A negative amount warns you before the limit of an authorised overdraft.",
  "Me prévenir": "Warn me",
  "Combien de jours avant que le compte passe sous le seuil (j = jours).": "How many days before the account drops below the threshold (j = days).",
  "{n} j": "{n} j",
  "Comptes surveillés — décoche un compte pour l'écarter, ou donne-lui un seuil à lui (vide : le seuil ci-dessus).": "Watched accounts — untick an account to leave it out, or give it its own threshold (empty: the threshold above).",
  "Comment c'est calculé : le solde du jour, puis ce qui est attendu sur ce compte d'ici là, en entrées comme en sorties — ce qui y revient chaque mois (prélèvements, virements, salaire) et le relevé d'une carte à débit différé. Les achats du quotidien ne sont pas devinés : c'est une estimation, à lire comme « au mieux ». L'alerte arrive en notification si « Solde bas » est activé sur l'appareil, et se lit aussi sur le calendrier du mois et le tableau de bord. Tu peux demander à l'assistant de changer ces réglages.": "How it is worked out: today's balance, then what is expected on this account until then, money in and money out — what comes back every month (direct debits, transfers, salary) and the statement of a deferred-debit card. Everyday purchases are not guessed: it is an estimate, to be read as “at best”. The alert comes as a notification if “Low balance” is on for the device, and also shows on the month calendar and the dashboard. You can ask the assistant to change these settings.",
  "{compte} est sous son seuil : {montant}.": "{compte} is below its threshold: {montant}.",
  "{compte} passerait à {montant} le {date}, après {cause}.": "{compte} would drop to {montant} on {date}, after {cause}.",
