  "ne pas l'afficher": "don't show it",
  "Soldes prévus ce jour-là": "Expected balances that day",
  "Régler l'alerte": "Set up the alert",
  "Aucun compte à suivre pour l'instant.": "No account to follow for now.",
  "La surveillance des soldes est coupée : aucun compte n'est signalé.": "Balance watching is off: no account is flagged.",
  "Aucun compte surveillé ne passe sous son seuil dans les {jours} jours.": "No watched account drops below its threshold in the next {jours} days.",
  "Comment c'est calculé : le solde du jour, puis ce qui est attendu sur ce compte, en entrées comme en sorties — ce qui y revient chaque mois (prélèvements, virements, salaire) et le relevé d'une carte à débit différé. Un prélèvement dont le jour habituel est passé depuis peu est compté dès aujourd'hui. Les achats du quotidien ne sont pas devinés : c'est une estimation, à lire comme « au mieux ».": "How it is worked out: today's balance, then what is expected on this account, money in and money out — what comes back every month (direct debits, transfers, salary) and the statement of a deferred-debit card. A direct debit whose usual day passed recently is counted from today. Everyday purchases are not guessed: it is an estimate, to be read as “at best”.",
  "sous le seuil": "below the threshold",
  "{montant} le {date}": "{montant} on {date}",
  "au-dessus du seuil": "above the threshold",
  "Pour rester au-dessus du seuil, il manquerait {montant} au plus bas, le {date}.": "To stay above the threshold, you would be {montant} short at the lowest point, on {date}.",
  "En pointillé : le seuil. Le point : le plus bas des jours à venir.": "Dashed: the threshold. The dot: the lowest of the coming days.",
  "Mouvements attendus": "Expected movements",
  "Solde après": "Balance after",
  "en retard, attendu d'un jour à l'autre": "late, expected any day now",
  "Rien d'attendu sur ce compte d'ici là.": "Nothing expected on this account until then.",
  "Mois (AAAA-MM)": "Month (YYYY-MM)",
  "Voir le compte signalé": ["See the flagged account", "See the {n} flagged accounts"],
  "Ce qui est attendu sur tes comptes, {n} jour à l'avance": ["What is expected on your accounts, {n} day ahead", "What is expected on your accounts, {n} days ahead"],
  "{n} compte est sous son seuil, ou y passerait dans les {jours} jours.": ["{n} account is below its threshold, or would be within {jours} days.", "{n} accounts are below their threshold, or would be within {jours} days."],
