  "Masquer ou afficher les montants": "Hide or show amounts",
  "Ce qui est classé en épargne : les versements vers un livret, une assurance-vie, un plan d'épargne.": "Whatever is categorised as savings: deposits to a savings account, life insurance or a savings plan.",
  "Revenus moins dépenses. L'épargne n'en est pas retirée : c'est ce qui reste avant de mettre de côté.": "Income minus spending. Savings are not taken out: it is what is left before putting money aside.",
  "Somme des revenus mensuels nets que tu as renseignés (salaires, loyers…).": "Sum of the net monthly income you have entered (salaries, rents…).",
  "Somme, ramenée au mois, de tes engagements en cours : la liste plus bas.": "Sum, per month, of your current commitments: the list further down.",
  "Revenus du foyer moins charges fixes : ce qu'il reste chaque mois pour tout le reste.": "Household income minus fixed costs: what is left each month for everything else.",
  "Revenus du foyer moins ce que tu dépenses vraiment par mois, en moyenne sur les trois derniers mois complets.": "Household income minus what you really spend per month, averaged over the last three full months.",
  "Achats déjà faits avec une carte à débit différé : la banque les prélèvera en une fois, à la date indiquée.": "Purchases already made with a deferred-debit card: the bank will charge them in one go, on the date shown.",
  "Dépenses du mois en cours, remboursements déduits. L'étiquette compare au mois dernier, à la même date.": "This month's spending, refunds deducted. The tag compares with last month, on the same date.",
  "Capital qu'il te reste à rembourser sur tes crédits, pour ta part.": "Principal you still have to repay on your loans, for your share.",
  "Valeur estimée moins capital restant dû sur les crédits du bien.": "Estimated value minus the principal still owed on the property's loans.",
  "Loyers d'une année rapportés au coût d'acquisition (prix et frais).": "One year of rent divided by the acquisition cost (price and fees).",
  "Densité": "Density",
  "Aérée": "Comfortable",
  "Compacte": "Compact",
  "« Compacte » resserre les marges et les lignes pour montrer plus d'opérations par écran, sans réduire le texte. Sur ordinateur seulement ; choix mémorisé sur cet appareil.": "“Compact” tightens margins and rows to show more transactions per screen, without shrinking the text. On computers only; the choice is remembered on this device.",
  "Tout ce que tu possèdes, avant de retirer ce que tu dois encore.": "Everything you own, before taking off what you still owe.",
  "Comptes courants et épargne : ce qui se mobilise sans vendre un bien ni un placement.": "Current accounts and savings: what you can use without selling a property or an investment.",
  "Compare mon engagement n° {id} « {nom} » à l'offre que je te joins et dis-moi laquelle est la plus avantageuse.": "Compare my commitment no. {id} “{nom}” with the offer I'm attaching and tell me which one is the better deal.",
