  "Changer un réglage": "Change a setting",
  "Change ce réglage de Pécule : ": "Change this Pécule setting: ",
  "Pose une question sur tes dépenses, tes comptes, ton patrimoine ou tes crédits, ou sur Pécule lui-même, joins une facture ou un document (trombone) pour le ranger, ou demande une action. Chaque action t'est soumise avant d'être faite.": "Ask a question about your spending, accounts, wealth or loans, or about Pécule itself, attach an invoice or document (paperclip) to file it, or ask for an action. Every action is shown to you before it is carried out.",
  "Tu pourras retirer cet accès à tout moment dans Réglages → Comptes et connexions.": "You can remove this access at any time in Settings → Accounts and connections.",
  "Chercher dans le manuel…": "Search the manual…",
