  "Par modèle": "By model",
  "Aucun appel à l'IA ce mois-là.": "No AI calls that month.",
  "Cache : {pct} de l'entrée relue à prix réduit": "Cache: {pct} of the input reread at a reduced price",
  "Pécule fait garder en cache ses consignes et le début de chaque conversation : le fournisseur les relit pour un dixième du prix. L'économie compare à ce que ces jetons auraient coûté au tarif normal, moins le surcoût de leur mise en cache.": "Pécule has its instructions and the start of each conversation kept in cache: the provider rereads them for a tenth of the price. The saving compares with what those tokens would have cost at the normal price, minus the extra cost of caching them.",
  "≈ {montant} économisés": "≈ {montant} saved",
  "≈ {montant} de surcoût": "≈ {montant} extra cost",
  "Tarif estimé : Pécule ne connaît pas le prix de ce modèle et le compte à celui de {modele}. Donne son tarif plus bas pour un coût juste.": "Estimated price: Pécule doesn't know this model's price and counts it at that of {modele}. Enter its price below for an accurate cost.",
  "Tes conversations et imports les plus coûteux": "Your most expensive conversations and imports",
  "Plafond du mois": "Monthly cap",
  "Dépense à ne pas dépasser": "Spend not to exceed",
  "L'administrateur reçoit une notification à {pct} % du plafond, puis quand il est atteint. Vide : aucun plafond.": "The administrator gets a notification at {pct}% of the cap, then when it is reached. Empty: no cap.",
  "Au plafond, mettre en pause les lectures de fond": "At the cap, pause background reading",
  "Les imports de dossier et la traduction des noms attendent le mois suivant, ou un plafond relevé. L'assistant et les fichiers déposés un à un répondent toujours.": "Folder imports and name translation wait for the next month, or a raised cap. The assistant and files dropped one at a time always respond.",
  "Le plafond et les tarifs se règlent par l'administrateur du foyer.": "The cap and the prices are set by the household administrator.",
  "tarif saisi": "price entered",
  "tarif public": "list price",
  "en service": "in use",
  "Entrée": "Input",
  "Tarif de l'entrée de {modele}": "Input price of {modele}",
  "Sortie": "Output",
  "Tarif de la sortie de {modele}": "Output price of {modele}",
  "Revenir au tarif d'origine": "Back to the original price",
  "{entree} l'entrée · {sortie} la sortie, par million de jetons": "{entree} input · {sortie} output, per million tokens",
  "Tarifs des modèles": "Model prices",
  "Tarifs en dollars, ceux que publie le fournisseur. Un modèle ou un déploiement que Pécule ne reconnaît pas est compté au tarif de {modele} tant que le sien n'est pas saisi ; ses appels déjà comptés sont alors recalculés.": "Prices in dollars, as published by the provider. A model or deployment Pécule doesn't recognise is counted at the price of {modele} until its own is entered; its calls already counted are then recalculated.",
  "Douze mois": "Twelve months",
  "Détail : {mois}": "Breakdown: {mois}",
  "Comment c'est compté : chaque appel à l'IA est noté avec ce que le fournisseur a compté (jetons lus et écrits, caractères lus à voix haute, audio transcrit), multiplié par son tarif public et converti en euros au cours du jour. C'est une estimation : ta facture fait foi. Interroger Pécule depuis l'appli Claude ne coûte rien ici, c'est ton abonnement Claude qui le porte.": "How it's counted: each AI call is recorded with what the provider counted (tokens read and written, characters read aloud, audio transcribed), multiplied by its list price and converted to euros at the day's rate. It's an estimate: your invoice is what counts. Querying Pécule from the Claude app costs nothing here; your Claude subscription covers it.",
  "Changer de fournisseur ou de modèle": "Change provider or model",
  "{montant} ce mois-ci": "{montant} this month",
